package dev.atalho.common.click;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/**
 * A redirect that happened, published by the API and consumed by the worker.
 *
 * <p>{@code eventId} is generated by the API and becomes the primary key of {@code click_events},
 * which keeps processing idempotent under at-least-once delivery. {@code ip} only travels inside
 * the message: the worker derives the country from it and then discards it.
 */
public record ClickEvent(
        UUID eventId,
        long linkId,
        String code,
        Instant occurredAt,
        String ip,
        String userAgent,
        String referrer) {

    public ClickEvent {
        Objects.requireNonNull(eventId, "eventId");
        Objects.requireNonNull(code, "code");
        Objects.requireNonNull(occurredAt, "occurredAt");
    }
}
